import{flattenedVerify}from"../flattened/verify.js";import{JWSInvalid,JWSSignatureVerificationFailed}from"../../util/errors.js";import{isObject}from"../../lib/type_checks.js";export async function generalVerify(e,r,t){if(!isObject(e))throw new JWSInvalid("General JWS must be an object");if(!Array.isArray(e.signatures)||!e.signatures.every(isObject))throw new JWSInvalid("JWS Signatures missing or incorrect type");for(const i of e.signatures)try{return await flattenedVerify({header:i.header,payload:e.payload,protected:i.protected,signature:i.signature},r,t)}catch{}throw new JWSSignatureVerificationFailed}